using CarRacer.Core.Discovery;
using CarRacer.Core.Session;
using CarRacer.Game.Menu;
using CarRacer.Game.Net;
using CarRacer.Game.Platform;
using CarRacer.Game.Screens;
using CarRacer.Game.Ui;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace CarRacer.Game
{
    /// <summary>
    /// Builds each screen from code so the Bootstrap scene can stay empty (and be generated by the
    /// build script). The screens are the menus and the track (practice alone, or in a hosted or
    /// joined session); each lives under one root object, which is destroyed when switching to
    /// another screen. Launched as a server, it hosts instead, with no screens (<see cref="DedicatedServer"/>).
    /// </summary>
    public static class Bootstrap
    {
        public const string SceneName = "Bootstrap";

        private static GameObject _screen;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        private static void OnFirstSceneLoaded()
        {
            if (SceneManager.GetActiveScene().name != SceneName)
            {
                return;
            }

            // The Linux server build always hosts with no player; any build does with -server (design doc §2.3).
            var options = ServerOptions.Parse(DedicatedServer.CommandLine());
#if UNITY_SERVER
            bool server = true;
#else
            bool server = options.IsServer;
#endif
            if (server)
            {
                Time.fixedDeltaTime = 0.02f;
                DedicatedServer.Run(options);
                return;
            }

            Application.targetFrameRate = 60;
            Screen.sleepTimeout = SleepTimeout.NeverSleep;
            GraphicsQuality.Apply();
            PerfOverlay.Install();
            ScreenFader.Install();

            // Fixed 50 Hz physics on every device (design doc §4).
            Time.fixedDeltaTime = 0.02f;
            ShowMainMenu();

            // A guest's camera app opens the host's QR code link, launching (or switching to) the game.
            Application.deepLinkActivated += OnLink;
            if (!string.IsNullOrEmpty(Application.absoluteURL))
            {
                OnLink(Application.absoluteURL);
            }
        }

        /// <summary>Joins the host in a join link (design doc §1.1), unless this phone is already in a session.</summary>
        private static void OnLink(string link)
        {
            if (!JoinLink.TryParse(link, out string address, out ushort port))
            {
                return;
            }

            var screen = _screen != null ? _screen.GetComponent<TrackScreen>() : null;
            if (screen != null && screen.Session != null && !screen.Session.Ended)
            {
                return;
            }

            string name = PlayerPrefs.GetString(MainMenu.NameKey, string.Empty);
            if (name.Length == 0)
            {
                // First launch: the name comes first, then the join.
                MainMenu.PendingJoin = (address, port);
                ShowMainMenu();
                return;
            }

            JoinGame(name, address, port);
        }

        /// <summary>Shows the main menu, with <paramref name="notice"/> (e.g. why a session ended) under the title.</summary>
        public static void ShowMainMenu(string notice = null)
        {
            var root = new GameObject(nameof(MainMenu));
            var camera = new GameObject("Main Camera").AddComponent<Camera>();
            camera.transform.SetParent(root.transform, false);
            camera.tag = "MainCamera";
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = UiKit.Background;

            // Without a listener the menu tune and button ticks are silent until a track screen adds one.
            camera.gameObject.AddComponent<AudioListener>();

            root.AddComponent<MainMenu>().Notice = notice;
            Show(root);
        }

        /// <summary>Practice: drive the track alone.</summary>
        public static void ShowPractice()
        {
            Show(TrackScreen.Create().gameObject);
        }

        /// <summary>Hosts a session: everyone who joins drives the track and waits in the lobby for the host to start.</summary>
        public static void HostGame(string playerName)
        {
            Show(TrackScreen.Create(startSession: () => NetworkSession.StartHosting(playerName)).gameObject);
        }

        public static void JoinGame(string playerName, string address, ushort port)
        {
            Show(TrackScreen.Create(startSession: () => NetworkSession.Join(playerName, address, port)).gameObject);
        }

        private static void Show(GameObject screen)
        {
            if (_screen != null)
            {
                Object.Destroy(_screen);
            }

            _screen = screen;
            ScreenFader.Cover();
        }
    }
}
